function naiveDup(arr){let c=0;for(let i=0;i<arr.length;i++){for(let j=i+1;j<arr.length;j++){c++;if(arr[i]===arr[j])return{found:true,c};}}return{found:false,c};}
function sortedDup(arr){let c=Math.ceil(arr.length*Math.log2(arr.length));arr.sort((a,b)=>a-b);for(let i=0;i<arr.length-1;i++){c++;if(arr[i]===arr[i+1])return{found:true,c};}return{found:false,c};}
const N=1000;
const data=Array.from({length:N},(_,i)=>i);
const a=naiveDup([...data]);
const b=sortedDup([...data]);
console.log('n='+N+' (no duplicates, worst case)');
console.log('naive O(n^2) comparisons:', a.c);
console.log('sort + neighbor O(n log n) comparisons:', b.c);
console.log('ratio naive/sorted:', Math.round(a.c/b.c)+'x');

