function contains(arr, v) {
  arr.sort((a, b) => a - b);        // sort to enable binary search
  let lo = 0, hi = arr.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (arr[mid] === v) return true;
    if (arr[mid] < v) lo = mid + 1; else hi = mid - 1;
  }
  return false;
}
